with filtered as (select *, date_format(paid_at, 'yyyy-MM') paid_at_label, to_date(paid_at) paid_at_date from payments where paid_at >= date '2023-11-13') select id, order_id, method, paid_at, status, sum(amount) over (partition by order_id, method order by amount, id rows between unbounded preceding and current row) running_amount, avg(amount) over (partition by order_id order by paid_at, id rows between 3 preceding and current row) amount_avg_3 from filtered where to_date(paid_at) >= '2024-04-01';
